/// <summary>
/// MPJ_2573_VendorRemittanceAdviceFormatChanges - Vpotula
/// Vendor Remittance advice format changes 
/// </summary>
[ExtensionOf(formStr(LedgerJournalTransVendPaym))]
final class METLedgerJournalTransVendPaym_Extension
{
}

Method.Source:
    /// <summary>
    /// MPJ_2573_VendorRemittanceAdviceFormatChanges
    /// Disable standard report and enable MET.
   /// </summary>
    public void enableBankPaymAdviceVendPrint()
    {
        next enableBankPaymAdviceVendPrint();

        boolean enabled = false;

        if (ledgerJournalTrans.PaymentStatus == CustVendPaymStatus::Sent)
        {
            enabled = true;
        }

        BankPaymAdviceVendPrint.Visible(false);
        BankPaymAdviceVendV2.Visible(false);
        METBankPaymAdviceVendV2.enabled(enabled);
    }

/// <summary>
/// Enables and disables various buttons.
/// </summary>
public void metEnableButtonsActive()
{
    METPaymReconDueDate.enabled(paymReconciliationSent.enabled());
    METPaymReconResend.enabled(paymReconciliationSent.enabled());
    METPaymReconWithdraw.enabled(paymReconciliationSent.enabled());
}
